  "Unsupported format: PDF, DOCX or XLSX required.": "Nepodporovaný formát: vyžaduje sa PDF, DOCX alebo XLSX.",
  "Update failed.": "Aktualizácia zlyhala.",
  "Updated": "Aktualizované",
  "Upload": "Nahrať",
  "Upload a document": "Nahrať dokument",
  "Upload a new version": "Nahrať novú verziu",
